FONTES = {'D62_FIX2_CONTRATO_ESCALA_PDF.txt': 'MEC-Serviços D62 FIX2 - PDF em A4 horizontal\nREVISION=MEC-SERVICOS-V0.1-D62-FIX2-ESCALA-PDF-2026-10-14\n\nO relatório agora gera PDF no backend, em A4 horizontal, com margens de 14 mm,\nfontes legíveis, tabelas na largura útil e rodapé com número da página.\nRelatórios maiores usam várias páginas, sem reduzir tudo para uma única folha.\nO arquivo independe do tema, largura e escala de impressão da página do portal.\nReportLab já integra as dependências da preparação de PDF D48.\n\nADM > Pagamentos > Resultado da administração > consultar período > Abrir\nrelatório do resultado. Clique Baixar PDF para obter o arquivo. Imprimir / salvar\nPDF abre o documento gerado em outra aba; use o botão de impressão do leitor.\nSe a aba for bloqueada ou fechada, o arquivo é baixado para abrir localmente.\nAo imprimir, use A4, orientação horizontal e tamanho real/escala 100%.\n\nO PDF usa o relatório completo conferido. Novos gastos, estornos ou alterações\nno período que mudem a consulta recusam a exportação; Atualizar relatório.\nCliente e fornecedor continuam sem acesso ao PDF, CSV e resultado interno.\nA visualização aberta pelo painel é fechada quando o painel é encerrado.\n\nHomologação: use contratação #5 / OS #5 da solicitação #12 no cenário atual.\nConfira venda R$ 14.380,75, custo R$ 12.505,00, ganho previsto R$ 1.875,75 e\ndespesas previstas R$ 100,00, enquanto estes forem os valores do seu serviço.\nO resultado previsto é R$ 1.775,75 e, sem despesas pagas, o resultado após\ndespesas pagas é R$ 1.875,75. Liquidação ainda pendente deixa ganho confirmado\ne resultado liquidado em zero. Nenhum destes valores é alterado pela correção.\nBaixe PDF: confira A4 horizontal, texto completo e todas as colunas dentro das\nmargens. Compare ao CSV e à tela. Teste também a visualização para impressão.\n\nAplicação: D62 FIX1 concluída, backup, testes seletivos isolados e build.\nSem novas tabelas. Os dois bancos, contas, arquivos e históricos são conferidos.\n', 'backend/app/api/rotas/despesa_administracao.py': 'from datetime import date\nfrom typing import Annotated\nfrom fastapi import APIRouter,Depends,HTTPException,Path,Query,Request,Response\nfrom sqlalchemy.orm import Session\nfrom backend.app.database.sessao import obter_banco\nfrom backend.app.schemas.despesa_administracao import RegistroDespesa,EstornoDespesa\nfrom backend.app.schemas.relatorio_resultado import RelatorioResultado\nfrom backend.app.services.relatorio_resultado import ServicoRelatorioResultado\nfrom backend.app.services.despesa_administracao import ServicoDespesasAdministracao\nroteador=APIRouter(prefix=\'/administracao/despesas\',tags=[\'despesas-reais-administracao\'])\nBanco=Annotated[Session,Depends(obter_banco)]\nID=Annotated[int,Path(gt=0,le=9_999_999_999_999)]\ndef servico(request,response,banco):\n    s=ServicoDespesasAdministracao(banco,request.state.usuario_acesso)\n    contexto=request.headers.get(\'x-mec-despesas-contexto\')\n    if contexto is not None and contexto!=s.contexto():raise HTTPException(409,detail=\'contexto_despesas_alterado\')\n    response.headers[\'Cache-Control\']=\'no-store\';return s\n@roteador.get(\'/resultado\')\ndef resultado(request:Request,response:Response,banco:Banco,inicio:date=Query(ge=date(1900,1,1),le=date(9999,12,30)),fim:date=Query(ge=date(1900,1,1),le=date(9999,12,30)),deslocamento:int=Query(0,ge=0,le=1_000_000),limite:int=Query(20,ge=1,le=100),pedidos_deslocamento:int=Query(0,ge=0,le=1_000_000),historico_deslocamento:int=Query(0,ge=0,le=1_000_000)):\n    return servico(request,response,banco).resultado(inicio,fim,deslocamento,limite,pedidos_deslocamento,historico_deslocamento)\n@roteador.get(\'/contratacoes/{contratacao_id}\')\ndef obter(contratacao_id:ID,request:Request,response:Response,banco:Banco,deslocamento:int=Query(0,ge=0,le=1_000_000),limite:int=Query(20,ge=1,le=100)):\n    return servico(request,response,banco).obter(contratacao_id,deslocamento,limite)\n@roteador.post(\'/contratacoes/{contratacao_id}\')\ndef registrar(contratacao_id:ID,dados:RegistroDespesa,request:Request,response:Response,banco:Banco):\n    return servico(request,response,banco).registrar(contratacao_id,dados)\n@roteador.post(\'/contratacoes/{contratacao_id}/despesas/{despesa_id}/estornar\')\ndef estornar(contratacao_id:ID,despesa_id:ID,dados:EstornoDespesa,request:Request,response:Response,banco:Banco):\n    return servico(request,response,banco).estornar(contratacao_id,despesa_id,dados)\n\n\ndef conferir_filtros_relatorio(request, csv=False):\n    permitidos = {\'inicio\', \'fim\'} | ({\'versao\'} if csv else set())\n    if any(k not in permitidos or len(request.query_params.getlist(k)) != 1 for k in request.query_params):\n        raise HTTPException(422, detail=\'filtro_relatorio_resultado_invalido\')\n\n@roteador.get(\'/resultado/relatorio\', response_model=RelatorioResultado)\ndef relatorio_resultado(request:Request,response:Response,banco:Banco,\n        inicio:date=Query(ge=date(1900,1,1),le=date(9999,12,30)),fim:date=Query(ge=date(1900,1,1),le=date(9999,12,30))):\n    s = servico(request,response,banco)\n    conferir_filtros_relatorio(request)\n    return ServicoRelatorioResultado(s).obter(inicio,fim)\n\n@roteador.get(\'/resultado/csv\')\ndef csv_resultado(request:Request,response:Response,banco:Banco,\n        inicio:date=Query(ge=date(1900,1,1),le=date(9999,12,30)),fim:date=Query(ge=date(1900,1,1),le=date(9999,12,30)),\n        versao:str=Query(pattern=r\'^[0-9a-f]{64}$\')):\n    s = servico(request,response,banco)\n    conferir_filtros_relatorio(request,csv=True)\n    conteudo, atual = ServicoRelatorioResultado(s).exportar(inicio,fim,versao)\n    return Response(conteudo,media_type=\'text/csv; charset=utf-8\',headers={\n        \'Content-Disposition\':f\'attachment; filename="MEC_SERVICOS_RESULTADO_ADMIN_{inicio}_{fim}.csv"\',\n        \'Cache-Control\':\'no-store\',\'X-MEC-Despesas-Contexto\':s.contexto(),\'X-MEC-Relatorio-Versao\':atual})\n\n\n@roteador.get(\'/resultado/pdf\')\ndef pdf_resultado(request:Request,response:Response,banco:Banco,\n        inicio:date=Query(ge=date(1900,1,1),le=date(9999,12,30)),fim:date=Query(ge=date(1900,1,1),le=date(9999,12,30)),\n        versao:str=Query(pattern=r\'^[0-9a-f]{64}$\')):\n    from hmac import compare_digest\n    from backend.app.services.pdf_resultado import gerar_pdf_resultado\n    s = servico(request,response,banco)\n    conferir_filtros_relatorio(request,csv=True)\n    r = ServicoRelatorioResultado(s).obter(inicio,fim)\n    if not compare_digest(versao,r[\'versao\']):raise HTTPException(409,detail=\'relatorio_resultado_alterado_atualize\')\n    return Response(gerar_pdf_resultado(r),media_type=\'application/pdf\',headers={\n        \'Content-Disposition\':f\'attachment; filename="MEC_SERVICOS_RESULTADO_ADMIN_{inicio}_{fim}.pdf"\',\n        \'Cache-Control\':\'no-store\',\'X-MEC-Despesas-Contexto\':s.contexto(),\'X-MEC-Relatorio-Versao\':r[\'versao\']})\n', 'backend/app/services/pdf_resultado.py': '"""PDF em dimensões físicas, sem depender da escala de impressão do navegador."""\nfrom datetime import datetime\nfrom decimal import Decimal\nfrom io import BytesIO\nfrom pathlib import Path\nfrom xml.sax.saxutils import escape\nfrom fastapi import HTTPException\nfrom backend.app.services.relatorio_resultado import CAMPOS, CATEGORIAS\n\ndef reais(valor):\n    return \'R$ \' + format(Decimal(valor), \',.2f\').replace(\',\', \'|\').replace(\'.\', \',\').replace(\'|\', \'.\')\n\ndef data(valor):\n    return datetime.fromisoformat(valor.replace(\'Z\', \'+00:00\')).strftime(\'%d/%m/%Y, %H:%M:%S\') + \' UTC\'\n\ndef gerar_pdf_resultado(r):\n    try:\n        import reportlab\n        from reportlab.lib import colors\n        from reportlab.lib.enums import TA_LEFT\n        from reportlab.lib.pagesizes import A4, landscape\n        from reportlab.lib.styles import ParagraphStyle\n        from reportlab.lib.units import mm\n        from reportlab.pdfbase import pdfmetrics\n        from reportlab.pdfbase.ttfonts import TTFont\n        from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, LongTable\n    except ImportError:\n        raise HTTPException(503, detail=\'dependencia_pdf_d48_ausente\') from None\n    fontes = Path(reportlab.__file__).resolve().parent / \'fonts\'\n    normal, negrito = \'Helvetica\', \'Helvetica-Bold\'\n    if (fontes / \'Vera.ttf\').is_file() and (fontes / \'VeraBd.ttf\').is_file():\n        normal, negrito = \'MecResultado62\', \'MecResultado62-Bold\'\n        if normal not in pdfmetrics.getRegisteredFontNames():\n            pdfmetrics.registerFont(TTFont(normal, str(fontes / \'Vera.ttf\')))\n            pdfmetrics.registerFont(TTFont(negrito, str(fontes / \'VeraBd.ttf\')))\n            pdfmetrics.registerFontFamily(normal, normal=normal, bold=negrito)\n    azul, cinza, linha = colors.HexColor(\'#17324f\'), colors.HexColor(\'#526577\'), colors.HexColor(\'#ced8e2\')\n    estilos = {\n        \'texto\': ParagraphStyle(\'texto62\', fontName=normal, fontSize=9, leading=13, textColor=azul, spaceAfter=5, splitLongWords=True),\n        \'titulo\': ParagraphStyle(\'titulo62\', fontName=negrito, fontSize=18, leading=22, textColor=azul, spaceAfter=7),\n        \'secao\': ParagraphStyle(\'secao62\', fontName=negrito, fontSize=11, leading=15, textColor=azul, spaceBefore=13, spaceAfter=6, keepWithNext=True),\n        \'celula\': ParagraphStyle(\'celula62\', fontName=normal, fontSize=8.5, leading=12, textColor=azul, alignment=TA_LEFT, splitLongWords=True),\n        \'cabecalho\': ParagraphStyle(\'cabecalho62\', fontName=negrito, fontSize=8.5, leading=12, textColor=azul, splitLongWords=True),\n        \'nota\': ParagraphStyle(\'nota62\', fontName=normal, fontSize=8, leading=11, textColor=cinza, spaceAfter=6),\n    }\n    def p(valor, estilo=\'celula\'):\n        return Paragraph(escape(str(valor)).replace(\'\\n\', \'<br/>\'), estilos[estilo])\n    largura_pagina, altura_pagina = landscape(A4)\n    margem = 14 * mm\n    largura = largura_pagina - 2 * margem - 12\n    saida = BytesIO()\n    doc = SimpleDocTemplate(saida, pagesize=(largura_pagina, altura_pagina), leftMargin=margem, rightMargin=margem,\n        topMargin=13 * mm, bottomMargin=15 * mm, title=\'MEC-Serviços - Resultado da administração\',\n        author=\'MEC-Serviços\', pageCompression=1)\n    partes = [p(\'MEC-Serviços | Administração | Uso exclusivo do ADM\', \'nota\'),\n        p(\'Relatório do resultado da administração\', \'titulo\'),\n        p(f"{r[\'inicio\'][8:10]}/{r[\'inicio\'][5:7]}/{r[\'inicio\'][:4]} a {r[\'fim\'][8:10]}/{r[\'fim\'][5:7]}/{r[\'fim\'][:4]} | {r[\'total\']} contratações | {r[\'liquidadas\']} liquidadas", \'texto\'),\n        p(\'Consulta: \' + data(r[\'gerado_em\']), \'nota\'), Spacer(1, 4)]\n    indicadores = []\n    for k, titulo in CAMPOS:\n        indicador = Paragraph(escape(titulo.removesuffix(\' (R$)\')) + \'<br/><font size="12"><b>\' + escape(reais(r[\'totais\'][k])) + \'</b></font>\', estilos[\'texto\'])\n        indicadores.append(indicador)\n    resumo = Table([indicadores[i:i+3] for i in range(0, 9, 3)], colWidths=[largura / 3] * 3, hAlign=\'LEFT\')\n    resumo.setStyle(TableStyle([(\'BACKGROUND\', (0, 0), (-1, -1), colors.HexColor(\'#f0f4f8\')),\n        (\'BOX\', (0, 0), (-1, -1), .5, linha), (\'INNERGRID\', (0, 0), (-1, -1), .5, linha),\n        (\'VALIGN\', (0, 0), (-1, -1), \'TOP\'), (\'LEFTPADDING\', (0, 0), (-1, -1), 9),\n        (\'RIGHTPADDING\', (0, 0), (-1, -1), 9), (\'TOPPADDING\', (0, 0), (-1, -1), 8), (\'BOTTOMPADDING\', (0, 0), (-1, -1), 7)]))\n    partes.append(resumo)\n    partes.extend([p(\'Critérios da consulta\', \'secao\'), p(\n        \'O período considera a criação da contratação em UTC. As despesas desses serviços entram em todas as datas de pagamento, inclusive quando registradas depois do período. A consulta acompanha o resultado dos serviços; o período não filtra o fluxo de caixa.\', \'texto\'), p(\n        \'Entram contratações ativas ou encerradas com preço formado pela administração. Despesas previstas são orçamento interno; despesas pagas somam gastos confirmados e excluem estornos. A liquidação exige entrega concluída, recebimento integral e repasse integral do custo, sem divergência. Novos gastos e estornos podem alterar o resultado.\', \'texto\')])\n    def tabela(titulos, registros, pesos):\n        dados = [[p(t, \'cabecalho\') for t in titulos]] + [[p(v) for v in reg] for reg in registros]\n        t = LongTable(dados, colWidths=[largura * v / sum(pesos) for v in pesos], repeatRows=1,\n            hAlign=\'LEFT\', splitByRow=1, splitInRow=1)\n        t.setStyle(TableStyle([(\'BACKGROUND\', (0, 0), (-1, 0), colors.HexColor(\'#e9eff5\')),\n            (\'LINEBELOW\', (0, 0), (-1, 0), .6, linha), (\'LINEBELOW\', (0, 1), (-1, -1), .35, linha),\n            (\'VALIGN\', (0, 0), (-1, -1), \'TOP\'), (\'LEFTPADDING\', (0, 0), (-1, -1), 6),\n            (\'RIGHTPADDING\', (0, 0), (-1, -1), 6), (\'TOPPADDING\', (0, 0), (-1, -1), 7),\n            (\'BOTTOMPADDING\', (0, 0), (-1, -1), 7)]))\n        return t\n    def contrato(c):\n        return f"#{c[\'contratacao_id\']}\\n" + (f"OS #{c[\'ordem_servico_id\']}" if c[\'ordem_servico_id\'] else \'Sem OS\')\n    partes.append(p(\'Formação do resultado por contratação\', \'secao\'))\n    if r[\'itens\']:\n        campos = (\'venda_cliente\', \'custo_fornecedor\', \'ganho_bruto_previsto\', \'despesas_previstas\', \'resultado_previsto\')\n        partes.append(tabela([\'Contratação / OS\', \'Cliente / fornecedor\', \'Venda ao cliente\', \'Custo do fornecedor\', \'Ganho bruto previsto\', \'Despesas previstas\', \'Resultado previsto\'],\n            [[contrato(c), c[\'cliente\'] + \'\\n\' + c[\'fornecedor\'], *(reais(c[k]) for k in campos)] for c in r[\'itens\']], [10, 20, 14, 14, 14, 14, 14]))\n        partes.append(p(\'Despesas e liquidação por contratação\', \'secao\'))\n        campos = (\'despesas_pagas\', \'resultado_apos_despesas\', \'ganho_bruto_confirmado\', \'resultado_liquidado_apos_despesas\')\n        partes.append(tabela([\'Contratação / OS\', \'Despesas pagas\', \'Resultado após despesas pagas\', \'Ganho bruto confirmado\', \'Resultado liquidado após despesas\', \'Liquidação\'],\n            [[contrato(c), *(reais(c[k]) for k in campos), \'Liquidada\' if c[\'liquidado\'] else \'Conferir valores e entrega\' if c[\'situacao\'] == \'verificar\' else \'Aguardando liquidação\'] for c in r[\'itens\']], [10, 17, 21, 17, 21, 18]))\n        partes.append(p(\'Criação das contratações (UTC): \' + \'; \'.join(f"#{c[\'contratacao_id\']}: {data(c[\'criada_em\'])}" for c in r[\'itens\']), \'nota\'))\n    else:\n        partes.append(p(\'Nenhuma contratação com preço formado neste período.\', \'texto\'))\n    partes.extend([p(\'Despesas registradas nos serviços do período\', \'secao\'), p(\n        f"{r[\'despesas_confirmadas\']} confirmadas | {r[\'despesas_estornadas\']} estornadas. Valor dos estornos: {reais(r[\'valor_estornado\'])}. Os estornos ficam no histórico e não compõem as despesas pagas.", \'texto\')])\n    if r[\'despesas\']:\n        registros = []\n        for d in r[\'despesas\']:\n            notas = f"Comprovante: {d[\'referencia\']}\\nRegistro: {d[\'registro_interno\']}\\nRegistrada por {d[\'administrador_nome\']} em {data(d[\'criada_em\'])}"\n            if d[\'status\'] == \'estornada\':\n                notas += \'\\nMotivo do estorno: \' + (d[\'motivo_estorno\'] or \'Consultar histórico da despesa\')\n                notas += \'\\nReferência do estorno: \' + (d[\'referencia_estorno\'] or \'Consultar histórico\')\n                if d[\'estornada_em\']: notas += \'\\nEstornada em: \' + data(d[\'estornada_em\'])\n            registros.append([f"Contratação #{d[\'contratacao_id\']}\\nDespesa #{d[\'id\']}", d[\'paga_em\'][8:10] + \'/\' + d[\'paga_em\'][5:7] + \'/\' + d[\'paga_em\'][:4] + \'\\n\' + CATEGORIAS[d[\'categoria\']],\n                d[\'descricao\'], reais(d[\'valor\']), \'Confirmada\' if d[\'status\'] == \'confirmada\' else \'Estornada\', notas])\n        partes.append(tabela([\'Contratação / despesa\', \'Pagamento / categoria\', \'Descrição\', \'Valor\', \'Estado\', \'Referência e registro interno\'], registros, [12, 13, 20, 13, 11, 31]))\n    else:\n        partes.append(p(\'Nenhuma despesa registrada nessas contratações.\', \'texto\'))\n    partes.extend([Spacer(1, 10), p(\'Resultado reservado à administração. Não substitui a apuração contábil nem inclui gastos ainda não registrados.\', \'nota\')])\n    def rodape(canvas, documento):\n        canvas.saveState()\n        canvas.setStrokeColor(linha); canvas.line(margem, 11 * mm, largura_pagina - margem, 11 * mm)\n        canvas.setFillColor(cinza); canvas.setFont(normal, 8)\n        canvas.drawString(margem, 7 * mm, \'MEC-Serviços | Administração | Uso exclusivo do ADM\')\n        canvas.drawRightString(largura_pagina - margem, 7 * mm, \'Página \' + str(documento.page))\n        canvas.restoreState()\n    doc.build(partes, onFirstPage=rodape, onLaterPages=rodape)\n    return saida.getvalue()\n', 'frontend/src/pages/formacao-preco/RelatorioResultado.css': '.rel62{margin:24px 0;scroll-margin-top:24px}.rel62:focus{outline:2px solid #70b6ff;outline-offset:4px}.rel62-acoes{margin-bottom:24px}.rel62-conteudo header{display:flex;justify-content:space-between;gap:20px;align-items:start}.rel62-conteudo .rel62-marca{font-weight:700;color:#8ec5ff;letter-spacing:.03em}.rel62-reservado{display:inline-block;border:1px solid #42617d;padding:8px 12px;border-radius:8px;color:#c4ddf6;font-size:13px}.rel62-conteudo section{margin:28px 0}.rel62-totais{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.rel62-totais>div{border:1px solid #30475d;border-radius:10px;background:#0e1c2c;padding:16px;overflow-wrap:anywhere}.rel62-totais span,.rel62-totais strong{display:block}.rel62-totais span{font-size:13px;color:#adc0d3;line-height:1.5}.rel62-totais strong{font-size:19px;margin-top:8px;color:#edf5fd}.rel62-scroll{overflow:auto;max-width:100%}.rel62-conteudo table{border-collapse:collapse;width:100%;font-size:13px}.rel62-conteudo td,.rel62-conteudo th{padding:12px 10px;border-bottom:1px solid #30475d;text-align:left;vertical-align:top;min-width:100px;max-width:320px;overflow-wrap:anywhere}.rel62-conteudo td p{margin:0 0 8px;white-space:pre-wrap}.rel62-conteudo small{display:block;font-size:12px;line-height:1.5;white-space:normal;margin-top:6px}.rel62-conteudo .rel62-negativo{color:#ffc5cc}.rel62-conteudo footer{border-top:1px solid #30475d;padding-top:16px;font-size:12px;color:#adc0d3}\n@media(max-width:760px){.rel62-totais{grid-template-columns:repeat(2,minmax(0,1fr))}.rel62-conteudo header{flex-direction:column}.rel62-acoes button{flex:1 1 150px}}@media(max-width:440px){.rel62-totais{grid-template-columns:1fr}}\n\n.rel62-pdf-ajuda{padding:12px 16px;border:1px solid #42617d;border-radius:8px;background:#163149}\n', 'frontend/src/pages/formacao-preco/RelatorioResultado.tsx': 'import {useEffect,useRef,useState} from "react";\nimport {useAuth} from "../../auth/AuthContext";\nimport {api} from "../../services/api";\nimport {categoriasDespesa,camposResultado,dataRelatorio,instanteRelatorio,moedaRelatorio,validarRelatorio,type RelatorioResultado as Dados} from "./dadosRelatorioResultado";\nimport "./RelatorioResultado.css";\n\nconst endpoint="/administracao/despesas/resultado";\nfunction erroRelatorio(e:unknown) {\n const r=(e as {response?:{status?:number;data?:unknown}}).response;\n if(r?.status===401||r?.status===403)return "Entre novamente com o perfil da administração para consultar este relatório.";\n if(r?.status===409)return "Os dados ou o acesso mudaram. Atualize o relatório antes de exportar.";\n if(r?.status===422)return "Confira o período: informe as datas em ordem e um intervalo de até dez anos.";\n return "Não foi possível conferir o relatório. Atualize e tente novamente.";\n}\nfunction Conteudo({r}:{r:Dados}) {\n return <article className="rel62-conteudo">\n  <header><div><p className="rel62-marca">MEC-Serviços · Administração</p><h2>Relatório do resultado da administração</h2><p>{dataRelatorio(r.inicio)} a {dataRelatorio(r.fim)} · {r.total} contratações · {r.liquidadas} liquidadas</p><p>Consulta: {instanteRelatorio(r.gerado_em)}</p></div><span className="rel62-reservado">Uso exclusivo do ADM</span></header>\n  <div className="rel62-totais">{camposResultado.map(([k,t])=><div key={k}><span>{t}</span><strong className={r.totais[k].startsWith("-")?"rel62-negativo":""}>{moedaRelatorio(r.totais[k])}</strong></div>)}</div>\n  <section><h3>Critérios da consulta</h3><p>O período considera a criação da contratação em UTC. As despesas vinculadas a essas contratações entram em todas as datas de pagamento, inclusive quando registradas depois do período. Esta consulta acompanha o resultado dos serviços; o período não filtra o fluxo de caixa.</p><p>Somente contratações ativas ou encerradas com preço formado pela administração entram nos totais. Pedidos ainda sem contratação, contratações canceladas e o histórico anterior continuam nas suas telas de acompanhamento.</p><p>Despesas previstas são o orçamento interno. Despesas pagas somam os gastos confirmados. A liquidação exige entrega concluída, recebimento integral do cliente e repasse integral do custo ao fornecedor, sem divergência. O resultado pode mudar com novos gastos ou estornos e considera somente despesas registradas.</p></section>\n  <section><h3>Formação do resultado por contratação</h3>{!r.total?<p>Nenhuma contratação com preço formado neste período.</p>:<div className="rel62-scroll"><table><thead><tr><th>Contratação / OS</th><th>Cliente / fornecedor</th><th>Venda ao cliente</th><th>Custo do fornecedor</th><th>Ganho bruto previsto</th><th>Despesas previstas</th><th>Resultado previsto</th></tr></thead><tbody>{r.itens.map(c=><tr key={c.contratacao_id}><th scope="row">#{c.contratacao_id}<small>{c.ordem_servico_id?`OS #${c.ordem_servico_id}`:"Sem OS"}</small><small>Criação: {instanteRelatorio(c.criada_em)}</small></th><td>{c.cliente}<small>{c.fornecedor}</small></td>{(["venda_cliente","custo_fornecedor","ganho_bruto_previsto","despesas_previstas","resultado_previsto"] as const).map(k=><td key={k}>{moedaRelatorio(c[k])}</td>)}</tr>)}</tbody></table></div>}</section>\n  {!!r.total&&<section><h3>Despesas e liquidação por contratação</h3><div className="rel62-scroll"><table><thead><tr><th>Contratação / OS</th><th>Despesas pagas</th><th>Resultado após despesas pagas</th><th>Ganho bruto confirmado</th><th>Resultado liquidado após despesas</th><th>Liquidação</th></tr></thead><tbody>{r.itens.map(c=><tr key={c.contratacao_id}><th scope="row">#{c.contratacao_id}<small>{c.ordem_servico_id?`OS #${c.ordem_servico_id}`:"Sem OS"}</small></th>{(["despesas_pagas","resultado_apos_despesas","ganho_bruto_confirmado","resultado_liquidado_apos_despesas"] as const).map(k=><td key={k} className={c[k].startsWith("-")?"rel62-negativo":""}>{moedaRelatorio(c[k])}</td>)}<td>{c.liquidado?"Liquidada":c.situacao==="verificar"?"Conferir valores e entrega":"Aguardando liquidação"}</td></tr>)}</tbody></table></div></section>}\n  <section><h3>Despesas registradas nos serviços do período</h3><p>{r.despesas_confirmadas} confirmadas · {r.despesas_estornadas} estornadas. Valor dos estornos: {moedaRelatorio(r.valor_estornado)}. Os registros estornados ficam no histórico e não compõem as despesas pagas.</p>\n   {!r.despesas.length?<p>Nenhuma despesa registrada nessas contratações.</p>:<div className="rel62-scroll"><table><thead><tr><th>Contratação / despesa</th><th>Pagamento / categoria</th><th>Descrição</th><th>Valor</th><th>Estado</th><th>Referência e registro interno</th></tr></thead><tbody>{r.despesas.map(d=><tr key={d.id}><th scope="row">Contratação #{d.contratacao_id}<small>Despesa #{d.id}</small></th><td>{dataRelatorio(d.paga_em)}<small>{categoriasDespesa[d.categoria]}</small></td><td>{d.descricao}</td><td>{moedaRelatorio(d.valor)}</td><td>{d.status==="confirmada"?"Confirmada":"Estornada"}{d.estornada_em&&<small>{instanteRelatorio(d.estornada_em)}</small>}</td><td><p>Comprovante: {d.referencia}</p><p>Registro: {d.registro_interno}</p><small>Registrada por {d.administrador_nome} · {instanteRelatorio(d.criada_em)}</small>{d.status==="estornada"&&<><p>Motivo do estorno: {d.motivo_estorno??"Consultar histórico da despesa"}</p><small>Referência do estorno: {d.referencia_estorno??"Consultar histórico"}</small></>}</td></tr>)}</tbody></table></div>}\n  </section><footer>Resultado reservado à administração. O relatório não substitui a apuração contábil nem inclui gastos ainda não registrados.</footer>\n </article>;\n}\nexport default function RelatorioResultado({contexto,inicio,fim,onFechar}:{contexto:string;inicio:string;fim:string;onFechar:()=>void}) {\n const {user}=useAuth(), atual=user?.role==="admin"?`${user.usuario_id}:admin:0`:"", autorizado=!!atual&&atual===contexto;\n const [dados,setDados]=useState<Dados|null>(null),[erro,setErro]=useState(""),[aviso,setAviso]=useState(""),[revisao,setRevisao]=useState(0),[operacao,setOperacao]=useState<""|"csv"|"pdf"|"imprimir">("");\n const baixando=operacao!=="",janelas=useRef(new Set<Window>());\n const painel=useRef<HTMLElement>(null),download=useRef<AbortController|null>(null),urls=useRef(new Set<string>());\n useEffect(()=>{\n  const controle=new AbortController();setDados(null);setErro("");setAviso("");\n  if(autorizado)void api.get<Dados>(endpoint+"/relatorio",{params:{inicio,fim},headers:{"X-MEC-Despesas-Contexto":contexto},signal:controle.signal,timeout:30000}).then(({data})=>{\n   if(controle.signal.aborted)return;validarRelatorio(data,contexto,inicio,fim);setDados(data);\n  }).catch(e=>{if(!controle.signal.aborted)setErro(erroRelatorio(e));});\n  return()=>controle.abort();\n },[autorizado,contexto,inicio,fim,revisao]);\n useEffect(()=>()=>{download.current?.abort();for(const janela of janelas.current)janela.close();janelas.current.clear();for(const url of urls.current)URL.revokeObjectURL(url);urls.current.clear();},[]);\n useEffect(()=>{painel.current?.scrollIntoView({behavior:"smooth",block:"start"});painel.current?.focus({preventScroll:true});},[]);\n useEffect(()=>{if(!dados){for(const janela of janelas.current)janela.close();janelas.current.clear();}},[dados]);\n async function exportar(formato:"csv"|"pdf"="csv", visualizar=false) {\n  if(!dados||baixando||!autorizado)return;\n  const janela=visualizar?window.open("about:blank","_blank"):null;\n  if(janela){janela.opener=null;janela.document.title="MEC-Serviços - Preparando PDF";janela.document.body.textContent="Preparando o PDF em A4 horizontal…";janelas.current.add(janela);}\n  const controle=new AbortController();download.current=controle;setOperacao(visualizar?"imprimir":formato);setErro("");setAviso("");\n  try {\n   const r=await api.get<Blob>(endpoint+"/"+formato,{params:{inicio,fim,versao:dados.versao},headers:{"X-MEC-Despesas-Contexto":contexto},responseType:"blob",signal:controle.signal,timeout:30000});\n   if(controle.signal.aborted)return;\n   const tipo=formato==="pdf"?"application/pdf":"text/csv";\n   if(r.headers["x-mec-despesas-contexto"]!==contexto || r.headers["x-mec-relatorio-versao"]!==dados.versao || !(r.data instanceof Blob) || !r.data.type.startsWith(tipo))throw new Error("exportacao_divergente");\n   if(formato==="pdf"&&(await r.data.slice(0,5).text())!=="%PDF-")throw new Error("pdf_invalido");\n   if(controle.signal.aborted)return;\n   const url=URL.createObjectURL(r.data);urls.current.add(url);\n   if(janela&&!janela.closed){janela.location.replace(url);setAviso("PDF aberto em A4 horizontal. Use Imprimir na visualização do PDF.");}\n   else {\n    const link=document.createElement("a");link.href=url;link.download=`MEC_SERVICOS_RESULTADO_ADMIN_${inicio}_${fim}.${formato}`;document.body.append(link);link.click();link.remove();\n    setTimeout(()=>{URL.revokeObjectURL(url);urls.current.delete(url);},1000);\n    setAviso(formato==="csv"?"CSV gerado com todas as contratações e despesas deste relatório.":visualizar?"PDF baixado. Abra o arquivo para imprimir; a visualização foi bloqueada ou fechada.":"PDF gerado em A4 horizontal, com todas as contratações e despesas do relatório.");\n   }\n  } catch(e) {\n   janela?.close();if(janela)janelas.current.delete(janela);\n   if(!controle.signal.aborted){setDados(null);setErro(erroRelatorio(e));}\n  } finally {if(!controle.signal.aborted)setOperacao("");}\n }\n if(!autorizado)return null;\n const carregando=!dados&&!erro;\n return <section className="fin-card rel62" aria-label="Relatório do resultado" ref={painel} tabIndex={-1}>\n  <div className="fin-header-acoes rel62-acoes"><button disabled={carregando||baixando} onClick={()=>setRevisao(v=>v+1)}>Atualizar relatório</button><button disabled={!dados||baixando} onClick={()=>void exportar()}>{operacao==="csv"?"Gerando CSV…":"Baixar CSV"}</button><button disabled={!dados||baixando} onClick={()=>void exportar("pdf")}>{operacao==="pdf"?"Gerando PDF…":"Baixar PDF"}</button><button disabled={!dados||baixando} onClick={()=>void exportar("pdf",true)}>{operacao==="imprimir"?"Preparando impressão…":"Imprimir / salvar PDF"}</button><button onClick={onFechar}>Fechar relatório</button></div>\n  {carregando&&<p role="status">Conferindo todas as contratações e despesas do período…</p>}{erro&&<p role="alert">{erro}</p>}{aviso&&<p role="status">{aviso}</p>}\n  {dados&&<><p className="rel62-pdf-ajuda">O PDF é gerado em A4 horizontal, com escala e margens próprias. Baixe o arquivo ou abra a visualização para imprimir.</p><Conteudo r={dados}/></>}\n </section>;\n}\n', 'tests/test_pdf_resultado_d62_fix2.py': '"""PDF físico, privado, completo e vinculado à versão consultada."""\nfrom io import BytesIO\nfrom copy import deepcopy\nimport pytest\nfrom pypdf import PdfReader\nfrom test_relatorio_resultado_d62 import despesas, precificacao, comercial, ambiente, modelo_acessos, obter, filtros, estado\nfrom test_despesas_administracao_d61 import registrar, estornar, entrar, DES\nfrom backend.app.services.pdf_resultado import gerar_pdf_resultado\n\nPDF = DES + \'/resultado/pdf\'\npytestmark = pytest.mark.acesso_real\n\ndef baixar(http, r, **kw):\n    return http.get(PDF, params={\'inicio\':r[\'inicio\'],\'fim\':r[\'fim\'],\'versao\':r[\'versao\'],**kw})\n\ndef ler(r):\n    assert r.status_code == 200, r.text\n    assert r.content.startswith(b\'%PDF-\') and r.headers[\'content-type\'] == \'application/pdf\'\n    assert r.headers[\'cache-control\'] == \'no-store\'\n    return PdfReader(BytesIO(r.content))\n\ndef texto(reader):\n    return \'\\n\'.join(p.extract_text() for p in reader.pages)\n\ndef test_pdf_a4_horizontal_completo_com_valores_exatos_e_sem_gravar(despesas):\n    http,_,sessoes,_,cid = despesas\n    assert registrar(http,cid,valor=\'400.01\').status_code == 200\n    r = obter(http);antes=estado(sessoes);resposta=baixar(http,r);reader=ler(resposta)\n    for pagina in reader.pages:\n        assert float(pagina.mediabox.width) == pytest.approx(841.89,abs=.1)\n        assert float(pagina.mediabox.height) == pytest.approx(595.28,abs=.1)\n    t=texto(reader)\n    for v in (\'1.800,00\',\'1.500,00\',\'400,01\',\'-100,01\',\'250,00\',\'COMPROVANTE-RESERVADO-D61\',\'Coleta teste interno D61\',\'Uso exclusivo do ADM\'):\n        assert v in t,v\n    assert f\'#{cid}\' in t and \'Página 1\' in t and \'Aguardando liquidação\' in t\n    assert resposta.headers[\'x-mec-relatorio-versao\']==r[\'versao\']\n    assert resposta.headers[\'x-mec-despesas-contexto\']==r[\'contexto\']\n    assert \'MEC_SERVICOS_RESULTADO_ADMIN_\' in resposta.headers[\'content-disposition\']\n    assert estado(sessoes)==antes\n\ndef test_pdf_tres_perfis_anonimo_e_contexto_divergente(despesas):\n    http,_,sessoes,_,cid=despesas\n    assert registrar(http,cid).status_code==200\n    r=obter(http);antes=estado(sessoes)\n    for perfil in (\'cliente\',\'fornecedor\'):\n        entrar(http,perfil);res=baixar(http,r)\n        assert res.status_code==403 and not res.content.startswith(b\'%PDF-\') and \'COMPROVANTE-RESERVADO\' not in res.text\n    http.cookies.clear();assert baixar(http,r).status_code==401\n    entrar(http,\'admin\')\n    assert http.get(PDF,params={**filtros(),\'versao\':r[\'versao\']},headers={\'X-MEC-Despesas-Contexto\':\'999:admin:0\'}).status_code==409\n    assert estado(sessoes)==antes\n\ndef test_pdf_antigo_recusado_apos_gasto_e_estorno(despesas):\n    http,_,_,_,cid=despesas;r=obter(http)\n    d=registrar(http,cid).json();assert baixar(http,r).status_code==409\n    r=obter(http);assert \'50,00\' in texto(ler(baixar(http,r)))\n    assert estornar(http,cid,d[\'despesa_id\'],registro_interno=\'Motivo interno do estorno PDF\').status_code==200\n    assert baixar(http,r).status_code==409\n    t=texto(ler(baixar(http,obter(http))))\n    assert \'Estornada\' in t and \'Motivo interno do estorno PDF\' in t\n\ndef test_pdf_recusa_filtros_ambiguos_e_exporta_periodo_vazio(despesas):\n    http=despesas[0];r=obter(http)\n    for params in ({\'fim\':\'9999-12-31\'},{\'limite\':1},{\'deslocamento\':20},{\'versao\':\'invalida\'}):\n        assert baixar(http,r,**params).status_code==422\n    assert http.get(PDF,params=filtros()).status_code==422\n    assert http.get(PDF,params=[*filtros().items(),(\'versao\',r[\'versao\']),(\'inicio\',\'2026-10-01\')]).status_code==422\n    r=obter(http,inicio=\'1900-01-01\',fim=\'1900-01-01\')\n    t=texto(ler(baixar(http,r)));assert \'Nenhuma contratação\' in t and \'R$ 0,00\' in t\n\ndef test_pdf_multipagina_nao_reduz_e_conserva_ultima_contratacao(despesas):\n    r=obter(despesas[0]);base=r[\'itens\'][0];r=deepcopy(r)\n    r[\'itens\']=[{**base,\'contratacao_id\':i,\'cliente\':\'Cliente completo \'+str(i),\'fornecedor\':\'Fornecedor \'+str(i)} for i in range(100,160)]\n    r[\'total\']=len(r[\'itens\'])\n    for k in r[\'totais\']:r[\'totais\'][k]=str(__import__(\'decimal\').Decimal(base[k])*60)\n    reader=PdfReader(BytesIO(gerar_pdf_resultado(r)));assert len(reader.pages)>3\n    t=texto(reader);assert \'#159\' in t and \'Cliente completo 159\' in t\n    assert all(\'MEC-Serviços\' in p.extract_text() and \'Página \' in p.extract_text() for p in reader.pages)\n    fontes=[]\n    for p in reader.pages:p.extract_text(visitor_text=lambda t,cm,tm,font,size:fontes.append(size) if t.strip() else None)\n    assert min(fontes)>=8\n\ndef test_pdf_texto_longo_e_marcacao_literal_sem_erro_de_paginacao(despesas):\n    http,_,_,_,cid=despesas\n    assert registrar(http,cid,descricao=\'<b>Descrição literal</b>\',registro_interno=\'Informação longa de teste. \'*70+\'FIM-DO-REGISTRO-LONGO\').status_code==200\n    reader=ler(baixar(http,obter(http)));t=texto(reader)\n    assert len(reader.pages)>=3\n    assert \'<b>Descrição literal</b>\' in t and \'FIM-DO-REGISTRO-LONGO\' in t\n'}

